/* =====================================================================
   MAM Lebendige Karten – Sprachen
   Sprache: ?lang=xx im Link (vom Schenkenden gewählt) > Sprache des Handys > Englisch.
   t('torte.title') liefert den Text, {name}/{n} werden ersetzt.
   ===================================================================== */
export const LANGS = { de: 'Deutsch', en: 'English', fr: 'Français', it: 'Italiano', es: 'Español', nl: 'Nederlands', pl: 'Polski', tr: 'Türkçe' };

function pick(){
  const q = new URLSearchParams(location.search).get('lang');
  if(q && LANGS[q]) return q;
  for(const l of (navigator.languages || [navigator.language || 'en'])){ const k = String(l).slice(0, 2).toLowerCase(); if(LANGS[k]) return k; }
  return 'en';
}
export const LANG = pick();
try{ document.documentElement.lang = LANG; }catch(e){}

