  'weihnacht.title': 'Frohe Weihnachten', 'weihnacht.sub': 'Tippe auf die Karte – und lass es schneien!', 'weihnacht.hint': 'Tipp auf die Karte!', 'weihnacht.msg': 'Ein frohes Fest!', 'weihnacht.msgN': 'Frohe Weihnachten, {name}!',
