  'papa.title': 'Goal Wall for Dad', 'papa.sub': 'The ball on the card wants into the goal wall! Six shots – three low, three high. How many go in?', 'papa.hint': 'Swipe the ball upwards – direction and length matter!', 'papa.msg': 'Happy Birthday, Dad!', 'papa.msgN': 'Happy Birthday, {name}!', 'papa.goal': 'GOAL!', 'papa.post': 'Off the board!', 'papa.wide': 'Wide!', 'papa.score': '{n} of {m} on target', 'papa.best': 'Your record: {n} goals',
