  'vatertag.title': 'Grill Master Dad', 'vatertag.sub': 'The sausages on the grill sizzle live: flip them at the golden moment, then onto the plate – but don’t let anything burn!', 'vatertag.hint': 'Tap a sausage when it shines golden!', 'vatertag.msg': 'Happy Father\'s Day!', 'vatertag.msgN': 'Happy Father\'s Day, {name}!', 'vatertag.raw': 'Still raw!', 'vatertag.perfect': 'Perfect!', 'vatertag.served': 'Served!', 'vatertag.burnt': 'Burnt!', 'vatertag.score': '{n} grill points', 'vatertag.best': 'Your record: {n} grill points',
