  'besserung.title': 'Teddy Care', 'besserung.sub': 'The teddy on the card is sick! Bring him tea, honey, a hot-water bottle and flowers – just drag them to his bed.', 'besserung.hint': 'Hold an item and drag it to the teddy!', 'besserung.msg': 'Get well soon!', 'besserung.msgN': 'Get well soon, {name}!', 'besserung.thanks': 'Thanks!', 'besserung.score': 'Teddy nursed back to health in {s} s', 'besserung.best': 'Fastest care: {s} s',
  'sekt.title': 'Bubbly Party', 'sekt.sub': 'The bottle on the card wants to pop! Shake it with quick up-and-down swipes, then fill all four glasses.', 'sekt.hint': 'Swipe quickly up and down over the bottle!', 'sekt.hint2': 'Hold your finger on a glass to fill it!', 'sekt.msg': 'Happy Birthday!', 'sekt.msgN': 'Happy Birthday, {name}!', 'sekt.pop': 'Pop!', 'sekt.full': 'Cheers!', 'sekt.over': 'Overflow!', 'sekt.score': 'All glasses full in {s} s', 'sekt.best': 'Your record: {s} s',
  'kerzen.title': 'Trick Candles', 'kerzen.sub': 'The candles on the cake are trick candles – they keep relighting! One breath blows out two at most. Can you get them all out at once?', 'kerzen.hint': 'Swipe across the flames to blow them out!', 'kerzen.msg': 'Happy Birthday!', 'kerzen.msgN': 'Happy Birthday, {name}!', 'kerzen.again': 'Lit again!', 'kerzen.score': 'All out after {s} s', 'kerzen.best': 'Your record: {s} s',
  'ostern.title': 'Egg Hunt', 'ostern.sub': 'The Easter eggs on the meadow are hiding! Now and then one peeks out – tap it fast and it hops into the basket.', 'ostern.hint': 'Tap the egg that is peeking out!', 'ostern.msg': 'Happy Easter!', 'ostern.msgN': 'Happy Easter, {name}!', 'ostern.hide': 'Hidden!', 'ostern.score': 'All 7 eggs found in {s} s', 'ostern.best': 'Fastest hunt: {s} s',
  'pinata.title': 'Birthday Piñata', 'pinata.sub': 'The piñata on the card is stuffed full! Hit it – as many points as the birthday person\'s age. A hard swipe counts double.', 'pinata.hint': 'Tap or swipe hard on the piñata!', 'pinata.msg': 'Happy Birthday!', 'pinata.msgN': 'Happy Birthday, {name}!', 'pinata.hit': 'Whack!', 'pinata.score': 'Burst after {n} hits', 'pinata.best': 'Your record: {n} hits',
  'golf.title': 'Birthday Putt', 'golf.sub': 'The golf ball on the card wants in the hole! Drag down away from the ball – the further, the harder. Careful, the green breaks slightly right.', 'golf.hint': 'Drag down from the ball and let go!', 'golf.msg': 'Happy Birthday!', 'golf.msgN': 'Happy Birthday, {name}!', 'golf.hole': 'In the hole!', 'golf.ace': 'Hole in one!', 'golf.short': 'Too short!', 'golf.long': 'Too long!', 'golf.score': 'Holed in {n} strokes', 'golf.best': 'Your record: {n} strokes',
  'hochzeitstag.title': 'Our Heart', 'hochzeitstag.sub': 'Trace the heart in the tree with your finger – the lanterns light up as you go, and your initials appear in the bark at the end.', 'hochzeitstag.hint': 'Follow the glowing dot around the heart!', 'hochzeitstag.msg': 'Happy Anniversary!', 'hochzeitstag.msgN': 'Happy Anniversary, {name}!', 'hochzeitstag.years': '{n} years – and more every day.', 'hochzeitstag.score': 'Heart carved in {s} s', 'hochzeitstag.best': 'Fastest heart: {s} s',
  'freundin.title': 'Our Moments', 'freundin.sub': 'The photos on the board light up one by one – remember the order and tap them back. One more moment every round!', 'freundin.hint': 'Watch, then tap the photos in the same order!', 'freundin.watch': 'Watch closely …', 'freundin.you': 'Your turn!', 'freundin.oops': 'Oops!', 'freundin.msg': 'For my best friend!', 'freundin.msgN': 'For my best friend {name}!', 'freundin.score': '{n} moments remembered', 'freundin.best': 'Your record: {n}',
  'oma.title': 'Grandma\'s Cake', 'oma.sub': 'Grandma\'s cake needs to be shared fairly! Swipe across it three times – each cut goes through the middle. How equal will the six slices be?', 'oma.hint': 'Swipe across the cake to cut it!', 'oma.msg': 'For the best grandma!', 'oma.msgN': 'For the best grandma, {name}!', 'oma.cut': 'Cut!', 'oma.score': '{n} % fairly shared', 'oma.best': 'Your record: {n} %', 'oma.perfect': 'Ruler-straight!', 'oma.ok': 'Almost like Grandma!', 'oma.bad': 'Grandma would have done it fairer …',
  'opa.title': 'Grandpa\'s Fishing Luck', 'opa.sub': 'The bobbers on the lake twitch – something\'s biting! Tap a bobber as soon as it dips under and pull out the fish. 40 seconds!', 'opa.hint': 'Tap the bobber when it dips under!', 'opa.msg': 'For the best grandpa!', 'opa.msgN': 'For the best grandpa, {name}!', 'opa.catch': 'Got one!', 'opa.early': 'Too early!', 'opa.late': 'It got away!', 'opa.score': '{n} fish caught', 'opa.best': 'Your record: {n} fish',
  'abitur.title': 'Caps Up!', 'abitur.sub': 'The graduation caps on the card are flying – keep them in the air! Tap a falling cap to toss it up again. Three landings and it\'s over.', 'abitur.hint': 'Tap the falling caps!', 'abitur.msg': 'You did it, graduate!', 'abitur.msgN': 'You did it, {name}!', 'abitur.note': 'With a {n} – impressive!', 'abitur.toss': 'Up!', 'abitur.drop': 'Landed!', 'abitur.score': '{n} tosses', 'abitur.best': 'Your record: {n} tosses',
  'schulanfang.title': 'Letter Blocks', 'schulanfang.sub': 'The wooden blocks on the table are jumbled! Tap them in the right order – they hop into a row and spell a word.', 'schulanfang.hint': 'Which word is it? Tap the first letter!', 'schulanfang.msg': 'Happy first day of school!', 'schulanfang.msgN': 'Happy first day of school, {name}!', 'schulanfang.wrong': 'Think again!', 'schulanfang.score': 'Solved in {s} s', 'schulanfang.best': 'Your record: {s} s',
  'festtag.title': 'Doves of Peace', 'festtag.sub': 'Five doves sit beside the candle. Tap them at your own pace – each one flies up and carries a light into the sky. No score, no rush.', 'festtag.hint': 'Tap a dove.', 'festtag.msg': 'Congratulations on your big day!', 'festtag.msgN': 'Congratulations on your big day, {name}!', 'festtag.msgA': 'Congratulations on your {anlass}!', 'festtag.msgNA': 'Congratulations on your {anlass}, {name}!', 'festtag.line': 'God bless you on your way.',
