  'abschied.title': 'Pack the Box', 'abschied.sub': 'The moving box is ready! Drag the cactus, favourite mug, photo and stapler from the desk into the box – as fast as you can.', 'abschied.hint': 'Drag the things into the box!', 'abschied.msg': 'All the best and good luck!', 'abschied.msgN': 'All the best, {name}, and good luck!', 'abschied.line': 'We\'ll miss you!', 'abschied.plopp': 'Plop!', 'abschied.score': 'Packed in {s} s', 'abschied.best': 'Best: {s} s',
  'umzug.title': 'Moving In!', 'umzug.sub': 'Boxes, plant, lamp and painting are still in the garden. Drag everything to the open front door – and the new home is ready!', 'umzug.hint': 'Drag the things to the door!', 'umzug.msg': 'Welcome to your new home!', 'umzug.msgN': 'Welcome to your new home, {name}!', 'umzug.line': 'Good luck and happy times within your new walls!', 'umzug.drin': 'Inside!', 'umzug.score': 'Moved in {s} s', 'umzug.best': 'Best: {s} s',
  'pruefung.title': 'Into the Bin!', 'pruefung.sub': 'Exam stress is over! Toss the five paper balls into the wastepaper basket.', 'pruefung.hint': 'Throw the paper balls into the basket!', 'pruefung.msg': 'Congratulations on passing your exam!', 'pruefung.msgN': 'Congratulations, {name} – you passed!', 'pruefung.line': 'All that studying paid off!', 'pruefung.treffer': 'Score!', 'pruefung.daneben': 'Missed!', 'pruefung.score': '{n} throws for 5 hits', 'pruefung.best': 'Best: {n}',
  'ersterburtstag.title': 'Duckling Serenade', 'ersterburtstag.sub': 'The rubber ducks want to sing! Tap them – every hop plays the next note of the birthday song.', 'ersterburtstag.hint': 'Tap the ducks!', 'ersterburtstag.msg': 'Happy 1st birthday!', 'ersterburtstag.msgN': 'Happy 1st birthday, {name}!', 'ersterburtstag.line': 'A whole year of wonders – here\'s to many more!',
  'fuehrerschein.title': 'Cone Slalom', 'fuehrerschein.sub': 'First lesson on the practice area: steer the red car past every cone in order – without knocking them over!', 'fuehrerschein.hint': 'Drag the car to the glowing cone!', 'fuehrerschein.msg': 'Congratulations on your driving licence!', 'fuehrerschein.msgN': 'Congratulations on your licence, {name}!', 'fuehrerschein.line': 'Safe travels, always!', 'fuehrerschein.bumm': 'Knocked over!', 'fuehrerschein.score': '{s} s ({e} faults)', 'fuehrerschein.best': 'Best: {s} s',
