  'danke.title': 'Bouquet de remerciement', 'danke.sub': 'Le bouquet de la carte se mélange – échange les morceaux jusqu\'à ce qu\'il soit entier !', 'danke.hint': 'Touche deux morceaux pour les échanger.', 'danke.msg': 'Merci du fond du cœur !', 'danke.msgN': 'Merci du fond du cœur, {name} !', 'danke.pair': 'Paire !', 'danke.score': 'Réussi en {n} coups', 'danke.best': 'Ton record : {n} coups',
  'besserung.title': 'Soigner le nounours', 'besserung.sub': 'Le nounours de la carte est malade ! Apporte-lui thé, miel, bouillotte et fleurs – fais-les glisser jusqu\'à son lit.', 'besserung.hint': 'Tiens un objet et glisse-le vers le nounours !', 'besserung.msg': 'Bon rétablissement !', 'besserung.msgN': 'Bon rétablissement, {name} !', 'besserung.thanks': 'Merci !', 'besserung.score': 'Nounours soigné en {s} s', 'besserung.best': 'Soin le plus rapide : {s} s',
  'sekt.title': 'Fête au champagne', 'sekt.sub': 'La bouteille de la carte veut sauter ! Secoue-la en glissant vite de haut en bas, puis remplis les quatre verres.', 'sekt.hint': 'Glisse vite de haut en bas sur la bouteille !', 'sekt.hint2': 'Garde le doigt sur un verre pour le remplir !', 'sekt.msg': 'Joyeux anniversaire !', 'sekt.msgN': 'Joyeux anniversaire, {name} !', 'sekt.pop': 'Pop !', 'sekt.full': 'Santé !', 'sekt.over': 'Ça déborde !', 'sekt.score': 'Tous les verres pleins en {s} s', 'sekt.best': 'Ton record : {s} s',
