  'advent.schutz': 'Beschermd!', 'advent.title': 'Kaarsentijd', 'advent.sub': 'Steek met de lucifer alle vier kaarsen aan – windvlagen blazen er steeds één uit. Houd ze vijf seconden alle vier brandend!', 'advent.hint': 'Sleep de lucifer naar de lontjes!', 'advent.aus': 'Uitgeblazen!', 'advent.msg': 'Een fijne adventstijd!', 'advent.msgN': 'Een fijne adventstijd, {name}!', 'advent.line': 'Gezellige uurtjes bij kaarslicht!', 'advent.score': 'Alle vier in {s} s', 'advent.best': 'Record: {s} s',
