  'oma.title': 'Ciasto babci', 'oma.sub': 'Ciasto babci trzeba sprawiedliwie podzielić! Przesuń trzy razy w poprzek – każde cięcie przechodzi przez środek. Jak równe będzie sześć kawałków?', 'oma.hint': 'Przesuń po cieście, aby je pokroić!', 'oma.msg': 'Dla najlepszej babci!', 'oma.msgN': 'Dla najlepszej babci, {name}!', 'oma.cut': 'Cięcie!', 'oma.score': '{n} % sprawiedliwie', 'oma.best': 'Twój rekord: {n} %', 'oma.perfect': 'Jak od linijki!', 'oma.ok': 'Prawie jak babcia!', 'oma.bad': 'Babcia zrobiłaby to sprawiedliwiej …',
  'opa.title': 'Rybackie szczęście dziadka', 'opa.sub': 'Spławiki na jeziorze drgają – bierze! Dotknij spławika, gdy tylko się zanurzy, i wyciągnij rybę. 40 sekund!', 'opa.hint': 'Dotknij spławika, gdy się zanurzy!', 'opa.msg': 'Dla najlepszego dziadka!', 'opa.msgN': 'Dla najlepszego dziadka, {name}!', 'opa.catch': 'Jest!', 'opa.early': 'Za wcześnie!', 'opa.late': 'Uciekła!', 'opa.score': 'Złowione ryby: {n}', 'opa.best': 'Twój rekord: {n} ryb',
  'abitur.title': 'Birety w górę!', 'abitur.sub': 'Birety z kartki latają – utrzymaj je w powietrzu! Dotknij spadającego biretu, by go podrzucić. Trzy lądowania i koniec.', 'abitur.hint': 'Dotykaj spadających biretów!', 'abitur.msg': 'Matura zdana!', 'abitur.msgN': 'Matura zdana, {name}!', 'abitur.note': 'Ze średnią {n} – brawo!', 'abitur.toss': 'W górę!', 'abitur.drop': 'Wylądował!', 'abitur.score': '{n} rzutów', 'abitur.best': 'Twój rekord: {n} rzutów',
  'schulanfang.title': 'Klocki z literami', 'schulanfang.sub': 'Drewniane klocki są pomieszane! Dotykaj ich we właściwej kolejności – wskoczą w rząd i ułożą słowo.', 'schulanfang.hint': 'Jakie to słowo? Dotknij pierwszej litery!', 'schulanfang.msg': 'Powodzenia w szkole!', 'schulanfang.msgN': 'Powodzenia w szkole, {name}!', 'schulanfang.wrong': 'Pomyśl jeszcze raz!', 'schulanfang.score': 'Rozwiązane w {s} s', 'schulanfang.best': 'Twój rekord: {s} s',
  'festtag.title': 'Gołębie pokoju', 'festtag.sub': 'Pięć gołębi siedzi obok świecy. Dotykaj ich spokojnie – każdy wzlatuje i niesie światło w niebo.', 'festtag.hint': 'Dotknij gołębia.', 'festtag.msg': 'Wszystkiego najlepszego w Twoim wielkim dniu!', 'festtag.msgN': 'Wszystkiego najlepszego w Twoim wielkim dniu, {name}!', 'festtag.msgA': 'Wszystkiego najlepszego z okazji: {anlass}!', 'festtag.msgNA': 'Wszystkiego najlepszego z okazji: {anlass}, {name}!', 'festtag.line': 'Niech Bóg Ci błogosławi.',
  'ruhestand.title': 'Do morza!', 'ruhestand.sub': 'Teczka, budzik, krawat, segregatory i kubek z biura leżą jeszcze na plaży. Chwyć je i wrzuć z rozmachem do morza – praca się skończyła!', 'ruhestand.hint': 'Chwyć rzecz z pracy i wrzuć ją do morza!', 'ruhestand.msg': 'Wspaniałej emerytury!', 'ruhestand.msgN': 'Wspaniałej emerytury, {name}!', 'ruhestand.line': 'Od teraz masz cały czas świata.', 'ruhestand.weg': 'Plusk!', 'ruhestand.score': '{n} rzutów', 'ruhestand.best': 'Rekord: {n}',
  'abschied.title': 'Pakowanie', 'abschied.sub': 'Karton już czeka! Przeciągnij kaktusa, ulubiony kubek, zdjęcie i zszywacz z biurka do kartonu – jak najszybciej.', 'abschied.hint': 'Przeciągnij rzeczy do kartonu!', 'abschied.msg': 'Wszystkiego dobrego i powodzenia!', 'abschied.msgN': 'Wszystkiego dobrego, {name}, i powodzenia!', 'abschied.line': 'Będzie nam ciebie brakować!', 'abschied.plopp': 'Plum!', 'abschied.score': 'Spakowane w {s} s', 'abschied.best': 'Rekord: {s} s',
  'umzug.title': 'Przeprowadzka!', 'umzug.sub': 'Kartony, roślina, lampa i obraz stoją jeszcze w ogrodzie. Przeciągnij wszystko do otwartych drzwi – i nowy dom gotowy!', 'umzug.hint': 'Przeciągnij rzeczy do drzwi!', 'umzug.msg': 'Witaj w nowym domu!', 'umzug.msgN': 'Witaj w nowym domu, {name}!', 'umzug.line': 'Szczęścia i pięknych chwil w nowych czterech ścianach!', 'umzug.drin': 'W środku!', 'umzug.score': 'Przeprowadzka w {s} s', 'umzug.best': 'Rekord: {s} s',
  'pruefung.title': 'Do kosza!', 'pruefung.sub': 'Stres egzaminacyjny minął! Wrzuć pięć papierowych kulek do kosza.', 'pruefung.hint': 'Wrzuć kulki do kosza!', 'pruefung.msg': 'Gratulacje zdanego egzaminu!', 'pruefung.msgN': 'Gratulacje, {name} – zdane!', 'pruefung.line': 'Cała nauka się opłaciła!', 'pruefung.treffer': 'Trafione!', 'pruefung.daneben': 'Pudło!', 'pruefung.score': '{n} rzutów na 5 trafień', 'pruefung.best': 'Rekord: {n}',
