  'fuehrerschein.title': 'Slalom między pachołkami', 'fuehrerschein.sub': 'Pierwsza lekcja na placu: prowadź czerwone auto obok każdego pachołka po kolei – nie przewracaj ich!', 'fuehrerschein.hint': 'Przeciągnij auto do świecącego pachołka!', 'fuehrerschein.msg': 'Gratulacje z okazji prawa jazdy!', 'fuehrerschein.msgN': 'Gratulacje z okazji prawa jazdy, {name}!', 'fuehrerschein.line': 'Szerokiej drogi!', 'fuehrerschein.bumm': 'Przewrócony!', 'fuehrerschein.score': '{s} s ({e} błędów)', 'fuehrerschein.best': 'Rekord: {s} s',
